namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
            new Notification { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        });

        // Simulate new notifications arriving over time
        _ = GenerateNotificationsAsync();
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId)
                              .OrderByDescending(n => n.Timestamp)
                              .ToList());
        }
    }

    private async Task GenerateNotificationsAsync()
    {
        var messages = new[]
        {
            "Someone liked your post.",
            "You have a new follower.",
            "System maintenance scheduled.",
            "Your report is ready to download.",
            "A comment was added to your thread.",
            "Security alert: new sign-in detected.",
            "Weekly summary is available.",
        };

        var rng = new Random();

        while (true)
        {
            await Task.Delay(TimeSpan.FromSeconds(rng.Next(8, 20)));

            lock (_lock)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = messages[rng.Next(messages.Length)],
                    Timestamp = DateTime.UtcNow,
                });
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private int lastSeenId;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if state wasn't restored from prerender
        notifications ??= await NotificationService.GetNotificationsAsync();

        // Track the highest ID so polling only fetches newer items
        if (notifications.Count > 0)
        {
            lastSeenId = notifications.Max(n => n.Id);
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive (never during prerender)
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), token);

            var newer = await NotificationService.GetNotificationsSinceAsync(lastSeenId);

            if (newer.Count > 0 && notifications is not null)
            {
                notifications.InsertRange(0, newer);
                lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
    }
}

