@@ -1,0 +1,89 @@
+@page "/notifications"
+@rendermode InteractiveServer
+@implements IDisposable
+@inject BlazorApp.Services.NotificationService NotificationService
+
+<PageTitle>Notifications</PageTitle>
+
+<h1>
+    Notifications
+    @if (notifications is not null)
+    {
+        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
+    }
+</h1>
+
+@if (notifications is null)
+{
+    <p><em>Loading...</em></p>
+}
+else if (notifications.Count == 0)
+{
+    <p>No notifications yet.</p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in notifications)
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <span>@n.Message</span>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    [PersistentState]
+    public List<Notification>? notifications { get; set; }
+
+    private int lastSeenId;
+    private CancellationTokenSource? cts;
+
+    protected override async Task OnInitializedAsync()
+    {
+        // Only fetch if state wasn't restored from prerender
+        notifications ??= await NotificationService.GetNotificationsAsync();
+
+        // Track the highest ID so polling only fetches newer items
+        if (notifications.Count > 0)
+        {
+            lastSeenId = notifications.Max(n => n.Id);
+        }
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // Start polling only after the component is interactive (never during prerender)
+            cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken token)
+    {
+        while (!token.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), token);
+
+            var newer = await NotificationService.GetNotificationsSinceAsync(lastSeenId);
+
+            if (newer.Count > 0 && notifications is not null)
+            {
+                notifications.InsertRange(0, newer);
+                lastSeenId = newer.Max(n => n.Id);
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        cts?.Cancel();
+        cts?.Dispose();
+    }
+}
+

